#include <iostream>
#include <vector>

using namespace std;

const long long MOD = 998244353;
vector<long long> powers;

void init(long long n, int k) {
    powers.resize(k);
    powers[0] = 1;
    for (int i = 1; i < k; ++i) {
        powers[i] = (n * powers[i - 1]) % MOD;
    }
}

long long ggt(long long a, long long b) {
    if (a < b) return ggt(b, a);
    if (b == 0) return a;
    return ggt(b, a % b);
}

long long gcd(long long a, long long b) {
    return a * b / ggt(a, b);
}

int gcdRange(long long n) {
    int result = 1;
    for (int i = 1; i <= n; ++i) {
        result = static_cast<int>(gcd(result, i));
    }
    return result;
}

void solve(int n, long long a, long long x, long long y, int k, long long M) {
    init(n, k);

    int gcdR = gcdRange(k - 1);
    vector<vector<long long>> r(gcdR, vector<long long>(k + 1));

    for (int i = 1; i <= k; ++i) {
        for (int j = 0; j < gcdR; ++j) {
            int jump = j - (j % (k + 1 - i));
            r[j][i] = ((n - 1LL) * r[j][i - 1]
                       + r[jump][i - 1]
                       + static_cast<long long>(j) * powers[i - 1]) % MOD;
        }
    }

    long long sum = 0;
    for (int i = 0; i < n; ++i) {
        sum += r[static_cast<int>(a % gcdR)][k]
             + ((((a / gcdR) * gcdR * k) % MOD) * powers[k - 1]) % MOD;
        sum %= MOD;
        a = (a * x + y) % M;
    }

    cout << sum << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    long long a, x, y, M;
    cin >> n >> a >> x >> y >> k >> M;

    solve(n, a, x, y, k, M);
    return 0;
}

